head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[selectbox > M > getDataListInfo]<br/>컴포넌트의 아이템이 정의된 DataCollection 의 정보를 반환합니다.",
    "validation" : [        
        "아이템이 정의된 DataCollection 정보를 객체로 반환합니다.",        
        "반환된 객체의 nodeset 속성은 아이템이 정의된 DataCollection 의 ID 를 'data:[DataCollection ID]' 형식으로 갖습니다.",
        "반환된 객체의 id 속성은 아이템이 정의된 DataCollection 의 ID 를 '[DataCollection ID]' 형식으로 갖습니다.",
        "반환된 객체의 value 속성은 아이템의 Value 값과 바인딩 된 컬럼의 ID 를 갖습니다.",
        "반환된 객체의 label 속성은 아이템의 Label 값과 바인딩 된 컬럼의 ID 를 갖습니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    scwin.comp_init();
};



// comp 재생성
scwin.comp_init = function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // target 생성    
    $c.gcm.createBasicSelectBox();
};



scwin.btn_getDataListInfo_onclick = function (e) {
    let rtn = '';

    rtn = target1.getDataListInfo();
    wf_body_bottom.getObj("scwin").setReturnValue("getDataListInfo : " + rtn);    
    wf_body_bottom.getObj("scwin").setReturnValue("getDataListInfo.nodeset : " + rtn.nodeset);
    wf_body_bottom.getObj("scwin").setReturnValue("getDataListInfo.id : " + rtn.id);
    wf_body_bottom.getObj("scwin").setReturnValue("getDataListInfo.value : " + rtn.value);
    wf_body_bottom.getObj("scwin").setReturnValue("getDataListInfo.label : " + rtn.label);
};
